package com.example.lending.domain;

import com.example.lending.common.DateUtils;

import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.Objects;
import java.util.UUID;

public class Loan {

    static final int LOAN_PERIOD_DAYS = 14;
    static final long LATE_FEE_PER_DAY = 100;

    private final UUID id;
    private final UUID bookId;
    private final UUID memberId;
    private final LocalDate loanedAt;
    private final LocalDate dueAt;
    private LocalDate returnedAt;

    private Loan(UUID id, UUID bookId, UUID memberId, LocalDate loanedAt, LocalDate dueAt, LocalDate returnedAt) {
        this.id = Objects.requireNonNull(id, "id");
        this.bookId = Objects.requireNonNull(bookId, "bookId");
        this.memberId = Objects.requireNonNull(memberId, "memberId");
        this.loanedAt = Objects.requireNonNull(loanedAt, "loanedAt");
        this.dueAt = Objects.requireNonNull(dueAt, "dueAt");
        if (dueAt.isBefore(loanedAt)) {
            throw new IllegalArgumentException("dueAt must not be before loanedAt");
        }
        this.returnedAt = returnedAt;
    }

    public static Loan start(UUID bookId, UUID memberId, LocalDate loanedAt) {
        return new Loan(UUID.randomUUID(), bookId, memberId, loanedAt,
                DateUtils.addDays(loanedAt, LOAN_PERIOD_DAYS), null);
    }

    public static Loan reconstitute(UUID id, UUID bookId, UUID memberId, LocalDate loanedAt, LocalDate dueAt,
                                    LocalDate returnedAt) {
        return new Loan(id, bookId, memberId, loanedAt, dueAt, returnedAt);
    }

    public void returnOn(LocalDate date) {
        if (isReturned()) {
            throw new LoanAlreadyReturnedException(id);
        }
        Objects.requireNonNull(date, "date");
        if (date.isBefore(loanedAt)) {
            throw new IllegalArgumentException("returnedAt must not be before loanedAt");
        }
        this.returnedAt = date;
    }

    public boolean isReturned() {
        return returnedAt != null;
    }

    public boolean isOverdue(LocalDate today) {
        return today.isAfter(dueAt);
    }

    public long overdueDays() {
        if (!isReturned()) {
            throw new IllegalStateException("loan is not returned yet");
        }
        return Math.max(0, ChronoUnit.DAYS.between(dueAt, returnedAt));
    }

    public long lateFee() {
        return overdueDays() * LATE_FEE_PER_DAY;
    }

    public UUID getId() {
        return id;
    }

    public UUID getBookId() {
        return bookId;
    }

    public UUID getMemberId() {
        return memberId;
    }

    public LocalDate getLoanedAt() {
        return loanedAt;
    }

    public LocalDate getDueAt() {
        return dueAt;
    }

    public LocalDate getReturnedAt() {
        return returnedAt;
    }
}
package com.example.lending.domain;

import java.util.Objects;
import java.util.Set;
import java.util.UUID;

public class Member {

    public static final int MAX_CONCURRENT_LOANS = 5;

    // 도서관 후원자: 대출 권수 제한 없음 (임시 조치, 설정으로 옮기는 것을 검토)
    private static final Set<UUID> LOAN_LIMIT_EXEMPT_IDS = Set.of(
            UUID.fromString("11111111-1111-1111-1111-111111111111"),
            UUID.fromString("22222222-2222-2222-2222-222222222222"),
            UUID.fromString("33333333-3333-3333-3333-333333333333"));

    private final UUID id;
    private final String name;

    private Member(UUID id, String name) {
        this.id = Objects.requireNonNull(id, "id");
        if (name == null || name.isBlank()) {
            throw new IllegalArgumentException("name must not be blank");
        }
        this.name = name;
    }

    public static Member register(String name) {
        return new Member(UUID.randomUUID(), name);
    }

    public static Member register(UUID id, String name) {
        return new Member(id, name);
    }

    public static Member reconstitute(UUID id, String name) {
        return new Member(id, name);
    }

    public void ensureCanBorrow(long activeLoanCount) {
        if (LOAN_LIMIT_EXEMPT_IDS.contains(id)) {
            return;
        }
        if (activeLoanCount >= MAX_CONCURRENT_LOANS) {
            throw new LoanLimitExceededException(id);
        }
    }

    public UUID getId() {
        return id;
    }

    public String getName() {
        return name;
    }
}
package com.example.lending.domain;

import java.util.Objects;
import java.util.UUID;

public class Book {

    private final UUID id;
    private final String title;
    private BookStatus status;

    private Book(UUID id, String title, BookStatus status) {
        this.id = Objects.requireNonNull(id, "id");
        if (title == null || title.isBlank()) {
            throw new IllegalArgumentException("title must not be blank");
        }
        this.title = title;
        this.status = Objects.requireNonNull(status, "status");
    }

    public static Book register(String title) {
        return new Book(UUID.randomUUID(), title, BookStatus.AVAILABLE);
    }

    public static Book reconstitute(UUID id, String title, BookStatus status) {
        return new Book(id, title, status);
    }

    public UUID getId() {
        return id;
    }

    public String getTitle() {
        return title;
    }

    public BookStatus getStatus() {
        return status;
    }

    public void setStatus(BookStatus status) {
        this.status = status;
    }

    public void returnFromLoan() {
        this.status = BookStatus.AVAILABLE;
    }

    public void ensureLoanable() {
        if (status == BookStatus.DISCARDED) {
            throw new BookDiscardedException(id);
        }
        if (status == BookStatus.ON_LOAN) {
            throw new BookAlreadyOnLoanException(id);
        }
    }

    public void ensureReservable() {
        if (status == BookStatus.DISCARDED) {
            throw new BookDiscardedException(id);
        }
        if (status == BookStatus.AVAILABLE) {
            throw new BookNotOnLoanException(id);
        }
    }

    public void discard() {
        if (status == BookStatus.ON_LOAN) {
            throw new CannotDiscardBookOnLoanException(id);
        }
        this.status = BookStatus.DISCARDED;
    }
}
package com.example.lending.adapter.in.web;

import com.example.lending.application.port.in.LoanBookUseCase;
import com.example.lending.application.port.in.LoanBookUseCase.LoanBookCommand;
import com.example.lending.application.port.in.ReturnBookUseCase;
import com.example.lending.domain.Loan;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

import java.time.LocalDate;
import java.util.UUID;

@RestController
@RequestMapping("/loans")
public class LoanController {

    private final LoanBookUseCase loanBookUseCase;
    private final ReturnBookUseCase returnBookUseCase;

    public LoanController(LoanBookUseCase loanBookUseCase, ReturnBookUseCase returnBookUseCase) {
        this.loanBookUseCase = loanBookUseCase;
        this.returnBookUseCase = returnBookUseCase;
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public LoanResponse loanBook(@RequestBody LoanRequest request) {
        Loan loan = loanBookUseCase.loanBook(new LoanBookCommand(request.bookId(), request.memberId(), request.loanedAt()));
        return LoanResponse.from(loan);
    }

    @PostMapping("/{loanId}/return")
    public LoanReturnResponse returnBook(@PathVariable UUID loanId,
                                         @RequestBody(required = false) ReturnLoanRequest request) {
        LocalDate returnedAt = request != null ? request.returnedAt() : null;
        Loan loan = returnBookUseCase.returnBook(loanId, returnedAt);
        return LoanReturnResponse.from(loan);
    }
}
