import org.springframework.stereotype.Component;

import java.util.UUID;

@Component
public class CreditCheckAdapter implements CheckCreditPort {

    private final CreditCheckClient creditCheckClient;

    public CreditCheckAdapter(CreditCheckClient creditCheckClient) {
        this.creditCheckClient = creditCheckClient;
    }

    @Override
    public CreditCheck check(UUID memberId, String memberName) {
        try {
            CreditCheckResponse response = creditCheckClient.check(memberId.toString(), memberName);
            return new CreditCheck(response.approved, response.score, response.reasonCodes, response.checkedAt,
                    response.provider != null ? response.provider.name : null,
                    response.provider != null ? response.provider.version : null);
        } catch (RuntimeException e) {
            // 조회 실패를 승인으로 취급하지 않는다 (대출 거절)
            throw new CreditCheckUnavailableException(e);
        }
    }
}

